mapper.update:
UPDATE STUDYMEMBER
	SET STUDY_OUTDATE = SYSDATE
WHERE MEM_ID = (SELECT B.MEM_ID
				FROM MEMBER A
				INNER JOIN STUDYMEMBER B  ON (B.MEM_ID = A.MEM_ID)
				WHERE A.MEM_ID = #{memId} AND B.STUDY_ID = #{studyId}
				) AND STUDY_ID = #{studyId}

UPDATE REPORT
SET
	ACTION_CONTENT = #{reportContent},
	ACTION_DATE = SYSDATE,
	ENDACTION_DATE = SYSDATE + #{endActionDate}
WHERE REPORT_ID = #{reportId}

UPDATE STUDYMEMBER SET
	STUDY_ROLL = (
	            CASE #{studyRoll}
	                WHEN '팀장' THEN 'L'
	                WHEN '팀원' THEN 'M'
	            END
	        )
WHERE MEM_ID = #{memId} AND STUDY_ID = #{studyId}

UPDATE STUDYMEMBER
	SET STUDY_OUTDATE = NULL
WHERE MEM_ID = (SELECT B.MEM_ID
				FROM MEMBER A
				INNER JOIN STUDYMEMBER B  ON (B.MEM_ID = A.MEM_ID)
				WHERE A.MEM_ID = #{memId} AND B.STUDY_ID = #{studyId}
				) AND STUDY_ID = #{studyId}
